for day_str, day_data in study_data.items():
    day_num = int(day_str)
    dl = day_data.get("daily_learning", {})
    
    guides = DETAILED_GUIDES.get(day_num) or BRIEF_GUIDES.get(day_num, {})
    
    for subj in ["math", "chemistry", "biology", "chinese", "english", "physics"]:
        if subj in dl and subj in guides:
            dl[subj]["practice_guide"] = guides[subj]
    
    day_data["daily_learning"] = dl

# 保存
with open(STUDY_DATA_PATH, "w", encoding="utf-8") as f:
    json.dump(study_data, f, ensure_ascii=False, indent=2)

# 验证
